package dev.voyage.workbench;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.io.*;import java.util.*;
public final class AgentService extends Service {
 Store store;volatile Rpc rpc;volatile boolean canceled,running;String projectId,taskId,attempt;StringBuilder reply=new StringBuilder();long flushed;boolean completed;
 public IBinder onBind(Intent i){return null;}
 public void onCreate(){super.onCreate();try{store=new Store(this);}catch(Exception e){throw new RuntimeException(e);}NotificationManager n=getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("agent","Voyage agent",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE);startForeground(1,new Notification.Builder(this,"agent").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Voyage Workbench").setContentText("Local agent is working").setContentIntent(open).build());}
 public int onStartCommand(Intent i,int flags,int startId){if(i==null){stopSelf();return START_NOT_STICKY;}String mode=i.getStringExtra("mode");if("stop".equals(mode)){canceled=true;try{if(projectId!=null)command(new JSONObject().put("type","taskStop").put("state","CANCELED"));}catch(Exception ignored){}if(rpc!=null)rpc.close();stopSelf();return START_NOT_STICKY;}if(running)return START_NOT_STICKY;running=true;canceled=false;new Thread(()->{try{if("login".equals(mode))login();else if("cli-login".equals(mode))CliLogin.run(this,i.getStringExtra("profileId"),i.getStringExtra("authMethod"),()->canceled);else run(i);}catch(Exception e){try{if(projectId!=null)command(new JSONObject().put("type","taskStop").put("state",canceled?"CANCELED":"FAILED").put("error",e.getMessage()));else if("login".equals(mode))store.setting("login",new JSONObject().put("error",e.getMessage()).toString());}catch(Exception ignored){}}finally{if(rpc!=null)rpc.close();running=false;store.setting("agentHeartbeat","0");stopSelf(startId);}},"voyage-agent").start();return START_NOT_STICKY;}
 void command(JSONObject c)throws Exception{c.put("taskId",taskId).put("attempt",attempt);store.dispatch(projectId,c);}
 JSONObject task()throws Exception{JSONArray tasks=store.project(projectId).getJSONArray("tasks");for(int j=0;j<tasks.length();j++)if(tasks.getJSONObject(j).getString("id").equals(taskId))return tasks.getJSONObject(j);throw new Exception("Task no longer exists");}
 void ensureTaskRunning()throws Exception{JSONObject current=task();if(canceled||!"RUNNING".equals(current.getString("state"))||!attempt.equals(current.getString("attempt")))throw new Exception("Task stopped");}
 void login()throws Exception{rpc=new Rpc(this,new File(getFilesDir(),"auth"));rpc.init();JSONObject start=rpc.rpc("account/login/start",new JSONObject().put("type","chatgptDeviceCode"),60);store.setting("login",start.toString());rpc.listener=e->{if("account/login/completed".equals(e.optString("method"))){start.put("complete",e.getJSONObject("params").optBoolean("success"));start.put("error",e.getJSONObject("params").optString("error"));store.setting("login",start.toString());completed=true;}};long end=System.currentTimeMillis()+15*60*1000;while(!completed&&!canceled&&System.currentTimeMillis()<end){store.setting("agentHeartbeat",Long.toString(System.currentTimeMillis()));try{rpc.pump();}catch(IOException e){if(!e.getMessage().startsWith("Timed out"))throw e;}}}
 void run(Intent intent)throws Exception{projectId=intent.getStringExtra("projectId");taskId=intent.getStringExtra("taskId");JSONObject t=task();attempt=t.getString("attempt");
 // Service creation recovers old work; this explicitly dispatched task alone is allowed to start.
 if(!"PREPARED".equals(t.getString("state")))throw new Exception("Task was interrupted before service startup. Start it again explicitly.");
 command(new JSONObject().put("type","taskRunning"));if(t.has("route")&&!"codex".equals(t.getJSONObject("route").getString("protocol"))){new Providers(this).run(t);completed=true;return;}File cwd=new File(getFilesDir(),"tasks/"+taskId);rpc=new Rpc(this,cwd);rpc.listener=this::event;rpc.init();JSONObject account=rpc.readAccount();if(account.isNull("account"))throw new Exception("Sign into Codex in Connection first.");
 ensureTaskRunning();
 boolean work="work".equals(t.getString("kind"));JSONArray definitions=new JSONArray(new String(getAssets().open(work?"tools-work.json":"tools-plan.json").readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));
 JSONObject started=rpc.rpc("thread/start",new JSONObject().put("model",t.has("route")&&!t.getJSONObject("route").optString("model").isEmpty()?t.getJSONObject("route").getString("model"):JSONObject.NULL).put("cwd",cwd.toString()).put("approvalPolicy","never").put("sandbox","read-only").put("dynamicTools",definitions).put("environments",new JSONArray()).put("developerInstructions",store.core.doc("agentSystem",work)),60);
 String thread=started.getJSONObject("thread").getString("id");command(new JSONObject().put("type","taskSession").put("sessionId",thread));JSONObject packet=(JSONObject)store.core.doc("assistantPacket",store.project(projectId),t);
 ensureTaskRunning();rpc.rpc("turn/start",new JSONObject().put("threadId",thread).put("input",new JSONArray().put(new JSONObject().put("type","text").put("text",packet.toString()))),60);
 long end=System.currentTimeMillis()+30*60*1000;while(!completed&&!canceled&&System.currentTimeMillis()<end){store.setting("agentHeartbeat",Long.toString(System.currentTimeMillis()));try{rpc.pump();}catch(IOException e){if(!e.getMessage().startsWith("Timed out"))throw e;}}if(!completed)throw new Exception(canceled?"Stopped by user":"Task exceeded its 30-minute limit");}
 void event(JSONObject event)throws Exception{String method=event.optString("method");JSONObject p=event.optJSONObject("params");if(event.has("id")&&event.has("method")){Object result;boolean success=true;try{if(!"item/tool/call".equals(method))throw new Exception("Unapproved provider request");result=tool(p.getString("tool"),p.getJSONObject("arguments"));}catch(Exception e){success=false;result=e.getMessage();}rpc.send(new JSONObject().put("id",event.get("id")).put("result",new JSONObject().put("success",success).put("contentItems",new JSONArray().put(new JSONObject().put("type","inputText").put("text",String.valueOf(result))))));}
 if("item/agentMessage/delta".equals(method)){reply.append(p.optString("delta"));if(System.currentTimeMillis()-flushed>1000){flushed=System.currentTimeMillis();command(new JSONObject().put("type","taskReply").put("text",reply.toString()));}}
 if("turn/completed".equals(method)){JSONObject turn=p.getJSONObject("turn");if(!"completed".equals(turn.optString("status")))throw new Exception("Provider interrupted the task: "+turn.optString("status"));command(new JSONObject().put("type","taskDone").put("text",reply.toString()));completed=true;}}
 Object tool(String name,JSONObject args)throws Exception{JSONObject t=task();if(!"RUNNING".equals(t.getString("state")))throw new Exception("Task stopped");String source=t.getString("work".equals(t.getString("kind"))?"stagedSource":"baseSource");switch(name){case "world_read":String raw=(String)store.core.doc("read",source,args.getJSONArray("path"));if(raw.length()>100000)throw new Exception("Read a smaller path using world_children");return new JSONObject().put("source",raw);case "world_children":JSONObject desc=(JSONObject)store.core.doc("describe",source,args.getJSONArray("path"));desc.remove("source");return desc;case "world_search":return store.core.doc("search",source,args.getString("query"));case "world_validate":return store.core.doc("validate",source,references());case "world_schema":JSONArray refs=references(),out=new JSONArray();for(int j=0;j<refs.length();j++)if(refs.getJSONObject(j).getString("section").equals(args.getString("section")))out.put(refs.get(j));return out;case "world_notes":return store.core.doc("readBuilderNotes",t.optJSONArray("builderNotes")==null?new JSONArray():t.getJSONArray("builderNotes"),args.getJSONArray("path"),args.optInt("offset",0));case "record_note_plan":command(new JSONObject().put("type","recordNotePlan").put("noteId",args.getString("noteId")).put("state",args.getString("state")).put("explanation",args.getString("explanation")).put("proposalId",args.optString("proposalId")));return new JSONObject().put("recorded",true).put("awaitingHumanReview",true);case "propose_artwork":if(!"plan".equals(t.getString("kind")))throw new Exception("Tool is unavailable for this stage");String artworkId=UUID.randomUUID().toString();command(new JSONObject().put("type","proposeArtwork").put("id",artworkId).put("request",args));return new JSONObject().put("proposalId",artworkId).put("awaitingHumanApproval",true).put("activeWorldUnchanged",true).put("generated",false);case "propose_work_order":String proposalId=UUID.randomUUID().toString();command(new JSONObject().put("type","proposeWorkOrder").put("id",proposalId).put("order",args));return new JSONObject().put("proposalId",proposalId).put("awaitingHumanApproval",true).put("activeWorldUnchanged",true);case "world_edit":args.put("type","taskEdit");command(args);return new JSONObject().put("staged",true).put("activeWorldUnchanged",true);default:throw new Exception("Unknown tool");}}
 JSONArray references()throws Exception{String saved=store.setting("references");return new JSONArray(saved.isEmpty()?new String(getAssets().open("public/references/sections.json").readAllBytes(),java.nio.charset.StandardCharsets.UTF_8):saved);}
 public void onDestroy(){canceled=true;if(rpc!=null)rpc.close();super.onDestroy();}
}
